import {serve} from '@hono/node-server';import {serveStatic} from '@hono/node-server/serve-static';import {Hono} from 'hono';import {z} from 'zod';import {calculate,type RequestInput} from './logic.js';
declare const process:{env:Record<string,string|undefined>};const maxBodyBytes=16_384;const schema=z.object({accession_key:z.string(),stable_units:z.number().int(),fragile_units:z.number().int(),packing_stations:z.number().int(),expedited:z.boolean()}).strict();
const response=(value:unknown,status=200,headers:Record<string,string>={})=>{if(Object.keys(headers).some(name=>['content-length','content-type','connection','transfer-encoding','x-content-type-options'].includes(name.toLowerCase())))return new Response(JSON.stringify({error:'invalid_response_headers',detail:'server-owned response header'}),{status:500,headers:{'content-type':'application/json'}});return new Response(JSON.stringify(value),{status,headers:{'content-type':'application/json',...headers}})};const error=(code:string,status:number,detail:string)=>response({error:code,detail},status);const zero=(v:RequestInput,state:string)=>({accession_key:v.accession_key,artifact_total:0,packing_units:0,capacity_units:0,overflow_units:0,inspection_rounds:0,priority_score:0,accession_state:state});const decide=(v:RequestInput,headers:Headers)=>{if((headers.get('authorization')??'')!=="Bearer accession-045")return response(zero(v,'authorization_required'),401,{"www-authenticate":"Bearer realm=artifact-accession"});if([v.stable_units,v.fragile_units,v.packing_stations].some(item=>item<0))return response(zero(v,'invalid'),422,{'x-validation':'nonnegative'});if(v.packing_stations===0&&v.stable_units+v.fragile_units>0)return response(zero(v,'invalid'),422,{'x-validation':'packing_stations'});const result=calculate(v);return response(result,201,{location:`/api/v9/artifact-accessions/${v.accession_key}`,'x-accession-state':result.accession_state});};
const app=new Hono();app.get('/status/artifact-accession-ready',()=>response({service:'Artifact Accession',ready:true}));app.post('/api/v9/artifact-accessions',async context=>{const media=(context.req.header('content-type')??'').split(';',1)[0]!.trim().toLowerCase();if(media!=='application/json'&&!media.endsWith('+json'))return error('json_content_type_required',415,'expected application/json');const declared=context.req.header('content-length');if(declared&&(!/^\d+$/.test(declared)||Number(declared)>maxBodyBytes))return error('body_too_large',413,'request body exceeds 16384 bytes');const raw=await context.req.arrayBuffer();if(raw.byteLength>maxBodyBytes)return error('body_too_large',413,'request body exceeds 16384 bytes');try{const parsed=schema.safeParse(JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(raw)));if(!parsed.success)return error('invalid_json',400,parsed.error.message);return decide(parsed.data,context.req.raw.headers)}catch(caught){return error('invalid_json',400,String(caught))}});app.all('/api/*',context=>error('not_found',404,`no API route ${context.req.path}`));app.get('/parley.js',serveStatic({path:process.env.FULLSTACK_045_BROWSER??'./dist/logic.js'}));app.get('/*',serveStatic({root:'./public'}));serve({fetch:app.fetch,hostname:'127.0.0.1',port:Number(process.env.PARLEY_WEB_PORT)});

