from __future__ import annotations
import json,os
from pathlib import Path
from fastapi import FastAPI,Request
from fastapi.responses import FileResponse,JSONResponse
from fastapi.staticfiles import StaticFiles
from pydantic import ValidationError
from logic import RequestInput,calculate
def zero(v:RequestInput,state:str)->dict[str,object]: return {'bid_key':v.bid_key,'generation_units':0,'battery_buffer_units':0,'grid_required_units':0,'grid_capacity_units':0,'delivered_units':0,'shortfall_units':0,'dispatch_windows':0,'bid_score':0,'bid_state':state}
def decide(v:RequestInput,request:Request)->JSONResponse:
    if request.headers.get('x-grid-key','') != 'grid-045': return outcome(zero(v,'authorization_required'),401,{'www-authenticate': 'GridKey'})
    if any(item < 0 for item in (v.solar_arrays,v.wind_turbines,v.storage_banks,v.interconnects,)): return outcome(zero(v,'invalid'),422,{'x-validation':'nonnegative'})
    if v.interconnects==0 and v.solar_arrays*9+v.wind_turbines*13>0: return outcome(zero(v,'invalid'),422,{'x-validation':'interconnects'})
    if v.duplicate_bid: return outcome(zero(v,'duplicate'),409,{'x-conflict':'duplicate_bid'})
    result=calculate(v)
    return outcome(result,202,{'location':f'/api/v9/microgrid-bids/{v.bid_key}','retry-after':'3','x-bid-state':str(result['bid_state'])})

MAX_BODY_BYTES=16_384
PUBLIC=Path(__file__).with_name('public')
def error(code:str,status:int,detail:str)->JSONResponse: return JSONResponse({'error':code,'detail':detail},status_code=status)
def outcome(body:dict[str,object],status:int,headers:dict[str,str])->JSONResponse:
    if any(name.lower() in {'content-length','content-type','connection','transfer-encoding','x-content-type-options'} for name in headers): return error('invalid_response_headers',500,'server-owned response header')
    return JSONResponse(body,status_code=status,headers=headers)
