const score=(solarArrays,windTurbines,storageBanks,interconnects,emergencyMode)=>{
  const generation=solarArrays*9+windTurbines*13;
  const required=generation+storageBanks*(emergencyMode?7:3);
  const capacity=interconnects*55;
  const delivered=Math.min(required,capacity);
  const shortfall=Math.max(required-capacity,0);
  return delivered+shortfall*4+Math.floor(required/31)*9;
};
