use serde::{Deserialize,Serialize};
#[derive(Deserialize)]#[serde(deny_unknown_fields)]pub struct RequestInput{pub accession_key:String,pub stable_units:i64,pub fragile_units:i64,pub packing_stations:i64,pub expedited:bool}
#[derive(Serialize)]pub struct ResponseOutput{pub accession_key:String,pub artifact_total:i64,pub packing_units:i64,pub capacity_units:i64,pub overflow_units:i64,pub inspection_rounds:i64,pub priority_score:i64,pub accession_state:String}
pub fn score(s:i64,f:i64,p:i64,e:bool)->i64{let total=s+f;let packing=s*6+f*11+if e{p*4}else{0};let overflow=(packing-p*40).max(0);packing+overflow*5+(total/5)*7}
pub fn calculate(v:&RequestInput)->ResponseOutput{let t=v.stable_units+v.fragile_units;let x=v.stable_units*6+v.fragile_units*11+if v.expedited{v.packing_stations*4}else{0};let c=v.packing_stations*40;let o=(x-c).max(0);ResponseOutput{accession_key:v.accession_key.clone(),artifact_total:t,packing_units:x,capacity_units:c,overflow_units:o,inspection_rounds:t/5,priority_score:score(v.stable_units,v.fragile_units,v.packing_stations,v.expedited),accession_state:if o==0{"accepted"}else{"queued"}.into()}}
#[unsafe(no_mangle)]pub extern "C" fn parley_browser_score(a0:i64,a1:i64,a2:i64,a3:i32)->i64{score(a0,a1,a2,a3!=0)}

