export type RequestInput={bid_key:string;solar_arrays:number;wind_turbines:number;storage_banks:number;interconnects:number;emergency_mode:boolean;duplicate_bid:boolean};export const score=(..._args:unknown[])=>0;export const calculate=(v:RequestInput)=>{const g=v.solar_arrays*9+v.wind_turbines*13,b=v.storage_banks*(v.emergency_mode?7:3),r=g+b,c=v.interconnects*55,s=Math.max(r-c,0);return {bid_key:v.bid_key,generation_units:g,battery_buffer_units:b,grid_required_units:r,grid_capacity_units:c,delivered_units:Math.min(r,c),shortfall_units:s,dispatch_windows:Math.trunc(r/31),bid_score:score(v.solar_arrays,v.wind_turbines,v.storage_banks,v.interconnects,v.emergency_mode),bid_state:s===0?'accepted':v.emergency_mode?'emergency_shortfall':'routine_shortfall'}};export async function loadParley(){return {microgrid_bid_score:(a0:number,a1:number,a2:number,a3:number,a4:boolean)=>BigInt(score(a0,a1,a2,a3,a4))}}
