    total = stable_units + fragile_units
    packing = stable_units * 6 + fragile_units * 11
    if expedited:
        packing += packing_stations * 4
    capacity = packing_stations * 40
    overflow = max(packing - capacity, 0)
    return packing + overflow * 5 + (total // 5) * 7
