const score=(solar_arrays,wind_turbines,storage_banks,interconnects,emergency_mode)=>{
  const generation=solar_arrays*9+wind_turbines*13;
  const buffer=storage_banks*(emergency_mode?7:3);
  const required=generation+buffer;
  const capacity=interconnects*55;
  const delivered=Math.min(required,capacity);
  const shortfall=Math.max(required-capacity,0);
  const dispatch_windows=Math.floor(required/31);
  return delivered+shortfall*4+dispatch_windows*9;
};
